"""Utilities for interacting with RGZ raw data."""

from collections.abc import Iterator, Sequence
import logging
import math
from typing import Any
import warnings

from astropy.io import fits
from astropy.wcs import WCS
from astropy.coordinates import SkyCoord
import astropy.wcs
import numpy as np
import requests

from rgz import constants
from rgz import units as u

# TODO(MatthewJA): This file contains much legacy code and needs updating.

logger = logging.getLogger(__name__)

# A string storing coordinates in HMSDMS format,
# as generated by astropy, with a space-separator.
# i.e. "HH MM SS.SS* [+-]DD MM SS.SS*"
type HMSDMS = str

# A JSON-serialisable dict.
type JSON = dict[str, Any]


# Default decimal precision used by astropy Angle.to_string when precision=None.
_ASTROPY_PRECISION_DEFAULT = 8
_HOURS_PER_ROTATION = 24.0
_MINUTES_PER_UNIT = 60
_SECONDS_PER_MINUTE = 60
_SECONDS_PER_UNIT = _MINUTES_PER_UNIT * _SECONDS_PER_MINUTE


def safe_skycoord_iterable(coords: SkyCoord) -> Iterator[SkyCoord]:
    """Type-safe tabular SkyCoord."""
    return iter(coords)  # type: ignore[reportReturnType]


def get_deg(coord: SkyCoord) -> tuple[np.float64, np.float64]:
    """Gets the RA/dec of a SkyCoord in degrees."""
    return coord.ra.deg, coord.dec.deg  # type: ignore[reportReturnType]


def get_wcs(im: fits.HDUList) -> astropy.wcs.WCS:
    """Extracts the 2D WCS from a FITS HDUList.

    Args:
        im: FITS HDUList whose primary HDU contains the image header.

    Returns:
        2D WCS.
    """
    header = im[0].header  # type: ignore[reportAttributeAccessIssue]
    with warnings.catch_warnings(
        action="ignore", category=astropy.wcs.FITSFixedWarning
    ):
        return WCS(header, naxis=2)


def _angle_to_str(angle: float, *, always_sign: bool = False) -> str:
    """Formats an angle (hours or degrees) as a space-separated sexagesimal string."""
    # copysign handles negative zero, which does matter for consistent
    # naming based on floats.
    is_negative = math.copysign(1.0, angle) < 0

    abs_angle = abs(angle)
    integral_angle = int(abs_angle // 1)
    total_minutes = (abs_angle % 1) * _MINUTES_PER_UNIT
    minutes = int(total_minutes // 1)
    seconds = (total_minutes % 1) * _SECONDS_PER_MINUTE

    # Carry over if seconds round up to 60 at precision limit.
    if seconds >= _SECONDS_PER_MINUTE - 10.0**-_ASTROPY_PRECISION_DEFAULT:
        seconds = 0.0
        minutes += 1
    if minutes >= _MINUTES_PER_UNIT:
        minutes = 0
        integral_angle += 1

    if is_negative:
        sign = "-"
    elif always_sign:
        sign = "+"
    else:
        sign = ""

    seconds_width = _ASTROPY_PRECISION_DEFAULT + 3
    seconds_str = (
        f"{seconds:0{seconds_width}.{_ASTROPY_PRECISION_DEFAULT}f}"
        .rstrip("0")
        .rstrip(".")
    )
    return f"{sign}{integral_angle:02d} {minutes:02d} {seconds_str}"


def coord_to_string(ra: u.Quantity[u.deg], dec: u.Quantity[u.deg]) -> HMSDMS:
    """Formats RA and Dec quantities as an HMSDMS string.

    Matches the output of `SkyCoord(ra, dec).to_string("hmsdms", sep=" ")`
    without constructing a `SkyCoord`.

    Args:
        ra: Right ascension.
        dec: Declination.

    Returns:
        Space-separated HMSDMS coordinate string.
    """
    ra_hours = float(ra.to_value(u.hourangle)) % _HOURS_PER_ROTATION
    dec_deg = float(dec.to_value(u.deg))
    return f"{_angle_to_str(ra_hours)} {_angle_to_str(dec_deg, always_sign=True)}"


def skycoord_to_string(coord: SkyCoord) -> HMSDMS:
    """Converts a SkyCoord to an HMSDMS string."""
    return coord_to_string(coord.ra, coord.dec)  # type: ignore[reportArgumentType]


def strings_to_skycoord(coords: Sequence[HMSDMS]) -> SkyCoord:
    """Parses space-separated HMSDMS strings into a SkyCoord.

    Matches `SkyCoord(coords, unit=("hourangle", "deg"))`, but avoids
    the regex used in Astropy, making it much faster.

    Args:
        coords: Space-separated HMSDMS coordinate strings.

    Returns:
        SkyCoord containing all coordinates.
    """
    ras_hours = np.empty(len(coords), dtype=np.float64)
    decs_deg = np.empty(len(coords), dtype=np.float64)

    for i, coord in enumerate(coords):
        ra_hours, ra_minutes, ra_seconds, dec_deg, dec_minutes, dec_seconds = (
            coord.split(" ")
        )
        ras_hours[i] = (
            float(ra_hours)
            + float(ra_minutes) / _MINUTES_PER_UNIT
            + float(ra_seconds) / _SECONDS_PER_UNIT
        )
        dec_sign = -1.0 if dec_deg.startswith("-") else 1.0
        decs_deg[i] = dec_sign * (
            abs(float(dec_deg))
            + float(dec_minutes) / _MINUTES_PER_UNIT
            + float(dec_seconds) / _SECONDS_PER_UNIT
        )

    return SkyCoord(ra=ras_hours * u.hourangle, dec=decs_deg * u.deg)

